}

class Solution {
    public int maximumNumberOfStringPairs(String[] words) {
        java.util.Map<String, Integer> seen = new java.util.HashMap<>();
        int pairs = 0;
        for (String word : words) {
            String reversed = "" + word.charAt(1) + word.charAt(0);
            pairs += seen.getOrDefault(reversed, 0);
            seen.put(word, seen.getOrDefault(word, 0) + 1);
        }
        return pairs;
    }
}

class Solution {
    public int maximumNumberOfStringPairs(String[] words) {
        int[][] count = new int[26][26];
        for (String word : words) {
            int first = word.charAt(0) - 'a';
            int second = word.charAt(1) - 'a';
            count[first][second]++;
        }
        int pairs = 0;
        for (int first = 0; first < 26; first++) {
            int same = count[first][first];
            pairs += same * (same - 1) / 2;
            for (int second = first + 1; second < 26; second++) {
                pairs += count[first][second] * count[second][first];
            }
        }
        return pairs;
    }
}

class Solution {
    public int maximumNumberOfStringPairs(String[] words) {
        int pairs = 0;
        for (int i = 0; i < words.length; i++) {
            for (int j = i + 1; j < words.length; j++) {
                if (words[i].charAt(0) == words[j].charAt(1)
                        && words[i].charAt(1) == words[j].charAt(0)) {
                    pairs++;
                }
            }
        }
        return pairs;
    }
}
